import math

def getGCD(arr):
	lenArr = len(arr)
	if lenArr == 0:
		return 0
	if lenArr == 1:
		return arr[0]
	ans = arr[0]
	for i in arr[1:lenArr]:
		ans = math.gcd(ans, i)
		if ans == 1:
			return ans
	return ans
import math
t = int(input())
for _ in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	pos = []
	neg = []
	for i in a:
		if i > 0:
			pos.append(i)
		elif i < 0:
			neg.append(-i)
	gp = getGCD(pos)
	gn = getGCD(neg)
	if n > 2 and len(pos) * len(neg) > 0:
		ans = 2 * math.gcd(gp, gn)
	else:
		ans = gp + gn
	print(ans)
